package com.oracle.banking.branch.controller;import com.oracle.banking.branch.dto.BranchDtos.*;import com.oracle.banking.branch.service.BranchService;import com.oracle.banking.shared.response.ApiResponse;import jakarta.validation.constraints.Pattern;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @Validated @RequestMapping("/api/branches") public class BranchController{private final BranchService s;public BranchController(BranchService s){this.s=s;}@GetMapping ApiResponse<List<Summary>> all(){return ApiResponse.success("Branches",s.all());}@GetMapping("/ifsc/{ifsc}") ApiResponse<Response> ifsc(@PathVariable("ifsc") @Pattern(regexp="^[A-Z]{4}0[A-Z0-9]{6}$",message="Invalid IFSC")String i){return ApiResponse.success("Branch",s.byIfsc(i));}@GetMapping("/{id}") ApiResponse<Response> id(@PathVariable("id") String i){return ApiResponse.success("Branch",s.byId(i));}}
